{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Cloud Run service is publicly accessible via allUsers",
      "resource": "google_cloud_run_service_iam_binding.search_service_public",
      "severity": "HIGH",
      "explanation": "The IAM binding grants the 'roles/run.invoker' role to 'allUsers', making the Cloud Run service anonymously accessible to anyone on the internet. This violates the principle of least privilege and exposes the service to unauthorized access, abuse, or data leakage."
    }
  ],
  "patched_code": "# REMOVED: google_cloud_run_service_iam_binding \"search_service_public\"\n# The resource granting 'allUsers' invoker access was removed to prevent public exposure.\n# To allow specific users or service accounts, replace with a binding using specific members,\n# e.g., members = [\"user:email@example.com\"] or \"serviceAccount:sa@project.iam.gserviceaccount.com\"\n",
  "fix_summary": "Removed the `google_cloud_run_service_iam_binding` resource that granted `roles/run.invoker` to `allUsers`, thereby eliminating anonymous public access to the Cloud Run service as per CKV_GCP_102."
}
